// Local Population III trial configuration; recompile after changing values.
// Comments describe the current driver; inactive legacy settings are marked.

// Header guard: prevents duplicate parameter definitions.
#ifndef PARAMETERS_H
#define PARAMETERS_H

// Execution and input paths.
#define CHUNKS "no" // "yes" reads chunk.out and offsets source IDs by chunk ID * N.
// Present-age limit comes from include/redshift_time.txt, not this legacy macro.
//#define Hubble 13.99E9 //13.803E9

#include "build_paths.h" // Generated by the local Makefile.
#define PREDIR BPOP_PROJECT_DIR // Repository root for shared tables and input paths.
#define SINGPTH BPOP_DATA_SUBDIR // BH spectra directory, relative to PREDIR.
#define PATH BPOP_DATA_SUBDIR // Isolated BBH catalogue directory, relative to PREDIR.
#define SEVN "pop3" // Input format/metallicity grid; "pop3" uses only Z = 1e-11.
// "yes" loads isolated efficiency data to bias Z draws; Pop III skips that bias.
#define MERGER_EFF_CORR "no"

// Population size and mass conventions.
#define N        1000000 // Candidates per run/chunk; output merger count can be smaller.
#define mmax     150. // Msun; larger values expand the estimated BH sinking radius/supply.
#define mmin     18.5 // Legacy minimum progenitor mass (Msun); unused by current sampling.
#define mslope  -2.35 // Legacy IMF exponent; current row sampling inherits the input IMF.
#define Zsun     0.019 // Solar metal mass fraction used to convert Z/Zsun outside Pop III.

// Candidate allocation, not cosmic merger-rate fractions; all fractions in [0,1].
// pYC + pGC + pNC = 1. YC/GC counts are truncated; NC gets the remaining candidates.
#define DynOvTot 0.9 // Dynamical fraction; isolated fraction = 1 - DynOvTot.
#define pYC      0.75 // Young-cluster share of dynamical candidates: N * DynOvTot * pYC.
#define pGC      0.15 // Globular-cluster share: N * DynOvTot * pGC.
#define pNC      0.1 // Nuclear share label; actual count is N - Niso - Nyc - Ngc.

// Optional added massive BHs; disabled here to use the supplied Pop III spectra.
#define uppergap "no" // "yes" allows phenomenological 50-100 Msun gap-BH replacements.
#define bhseed   "no" // Seed recipe: no, bifrost, vms, yes, density, or seed.
#define bifZ     0.001 // Maximum Z for bifrost seeds; inactive unless bhseed="bifrost".
#define bhpisn   270. // Msun; bifrost collision product must exceed this to form a seed.
#define fupgp    0.15 // Gap-replacement probability; overridden by dicarlo/oldicarlo.
#define mass_gap  60.0 // Msun; replacement threshold when uppergap="yes", not a mass cap.
#define upgtp   "dicarlo" // Sets Z-dependent gap probability; still needs uppergap="yes".


// Formation-redshift sampling: continuous = uniform z in [0,15], not uniform age.
// MF17 = cosmic SFR shape; KR13 = uniform z in [2,10]; single = z=2; bigbang = z=20.
#define SFRTYPE_ISO "continuous" // Isolated and young-cluster formation epochs.
#define SFRTYPE_CLU "continuous" // GC/NC epochs; EB18_MF17 uses EB18 for GC, MF17 for NC.

// Dynamical BH reservoir and initial binary-formation delay.
#define mixing  0.5 // Mixed/binary-origin spectrum probability; 0=single, 1=mixed only.
#define fbin    0.0 // Probability of skipping formation delay by setting t3bb=0; [0,1].

// Cluster structure sets density, encounter times, and escape/retention speeds.
// Choices: AS20, Marks12, Rantala24, Mapelli20, seed; Pop III uses generic clusters.
#define TagR "AS20" // Mass/radius recipe; "seed" uses fixed MCL_popIII/RCL_popIII.

// Initial separation = hard-binary scale * nonnegative Gaussian(mean=1, sigma=SSMA).
#define SSMA 0.3 // Dimensionless scatter; negative selects uniform separation 0.1-0.2 AU.

// Cluster evolution and controlled experiments.
#define CLfill       "GG23" // Evolution recipe affects delays/retention; other modes partial.
#define MonoZ        "no" // "yes" forces mono_Z; Pop III is already single-Z by default.
// Also used by "single" SFR or TagR="seed"; Pop III input tables require 1e-11.
#define mono_Z       0.0002 // Metal mass fraction for the explicit fixed-Z override.
#define cluster_test "no" // "yes" selects one dynamical channel and alters epochs/masses.
#define cluster_test_env "NC" // Test channel: YC, GC, NC; DynOvTot still sets isolated share.
#define msmbhmax 5.E7 // Msun; stop hierarchical growth when the primary exceeds this mass.

// Seed parameters; inactive with bhseed="no".
#define f_seed    0.2 // Seed probability [0,1], subject to the selected recipe's conditions.
#define maxseed   1000.0 // Msun; upper seed mass for bhseed="yes" or "density".
#define minseed   100.0 // Msun; lower seed mass for those power-law seed recipes.
#define seedslope 3.0 // p(Mseed) proportional to Mseed^-seedslope; larger favors low masses.

// Gap-mass sampling; inactive with uppergap="no".
#define a_gp 2.0 // p(Mgap) proportional to Mgap^-a_gp; larger favors low gap masses.

// Higher-generation companions are not implemented; primary recycling still works.
#define highgen "no" // Currently affects output naming only.

// Non-Pop-III metallicity distributions; bypassed by the fixed Z=1e-11 branch.
#define sigma_metal_iso  0.6 // Scatter in log10(Z/Zsun), dex; broader for larger values.
#define sigma_distri_iso "Mapelli" // Mean Z(z) recipe for isolated binaries/young clusters.
#define sigma_metal_clu  0.6 // GC/NC log-metallicity scatter, dex; larger broadens Z draws.
#define sigma_distri_clu "Elbadry19" // Cluster mean Z(z) recipe when that branch is used.

// Natal spins affect effective spin, remnant spin, recoil, and subsequent retention.
#define spinlb  "fuller" // "fuller" assigns chi=0.001; also random, gaussian, bavera, etc.
#define obslope  0.0 // Legacy mass-selection bias exponent; unused by current row sampling.

// Legacy switches retained for output directory naming; no current physics effect.
#define sfr_only "no" // Former SFR-only switch; now naming only.

// Legacy dynamical metallicity settings (replaced by sigma_* prescriptions above).
#define zdyn       "logflat" // Former Z distribution selector; now naming only.
#define zslope     -1.5 // Former dynamical metallicity-weight exponent; unused.

// Active dynamical pairing control: nouniform draws companion BHs from the spectra.
#define MRATIO "nouniform" // Alternatives: uniform, pwl, gss draw q=Msecondary/Mprimary.
#define MRATIO_SLOPE -1.0 // For pwl only: p(q) proportional to q^-MRATIO_SLOPE.


// Legacy isolated metallicity/bias settings; no current physics effect.
#define zdist       "logflat" // Former isolated Z selector; now naming only.
#define zdivi       0.0 // Former metallicity-division setting; now naming only.
#define correction  "no" // Former correction switch; now naming only.
#define slope       -1.5 // Former isolated metallicity-weight exponent; unused.

// Isolated spin tilt: cos(theta)=2*U^(1/(INDEX_ALIGN+1))-1; 0 isotropic, larger aligned.
#define INDEX_ALIGN 8.0 // Dynamical angle draws override this and remain isotropic.


// Fixed seed experiment; the Pop III label alone does not activate these settings.
#define MCL_popIII 1.E6 // Msun; fixed cluster mass only with TagR="seed".
#define RCL_popIII 1.0 // pc; fixed cluster half-mass radius only with TagR="seed".
#define MBH_popIII 300.0 // Msun; seed primary for bhseed="seed" AND TagR="seed".
#define aBH_popIII 0.0001 // Nominal seed chi; later natal-spin assignment overwrites it.
  



// Input record widths; must match the supplied files, not population size.
#define kpar 20 // Numeric columns per isolated BBH input record (text header skipped).
#define spar 5 // Numeric columns per single/mixed BH spectrum record.
// Metallicity-grid length is selected in the driver by SEVN, not this legacy macro.
//#define numZ 12

// Legacy histogram dimensions; current direct-row sampling does not use them.
#define bin_st 50 // Progenitor-mass bins in the old mixed-spectrum sampler.
#define nsize 80 // BH-remnant mass bins in the old sampler.
#define tsize 80 // BH-formation time bins in the old sampler.
#define vsize 80 // Natal-kick speed bins in the old sampler.

#endif
